entry.content:
&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/two-sum/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given an array of integers &lt;code&gt;nums&lt;/code&gt; and an integer &lt;code&gt;target&lt;/code&gt;, return &lt;em&gt;indices of the two numbers such that they add up to &lt;code&gt;target&lt;/code&gt;&lt;/em&gt;.&lt;/p&gt;
&lt;p&gt;You may assume that each input would have &lt;strong&gt;&lt;em&gt;exactly&lt;/em&gt; one solution&lt;/strong&gt;, and you may not use the &lt;em&gt;same&lt;/em&gt; element twice.&lt;/p&gt;
&lt;p&gt;You can return the answer in any order.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [2,7,11,15], target = 9&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [0,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; Because nums[0] + nums[1] == 9, we return [0, 1].&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [3,2,4], target = 6&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [1,2]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [3,3], target = 6&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [0,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;2 &amp;lt;= nums.length &amp;lt;= 10^4&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;-10^9 &amp;lt;= nums[i] &amp;lt;= 10^9&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;-10^9 &amp;lt;= target &amp;lt;= 10^9&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Only one valid answer exists.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Follow-up:&lt;/strong&gt; Can you come up with an algorithm that is less than &lt;code&gt;O(n^2)&lt;/code&gt; time complexity?&lt;/p&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; two_sum&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; target&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // caching visited numbers and corresponding indices&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; cache&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;collections&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;HashMap&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;new&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;();&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        for&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; num&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; in&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;iter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;enumerate&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;() {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;            match&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; cache&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;get&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;num&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;) {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // found cached index, return&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;                Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;pos&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; return&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; pos&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // not found, cache it&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;                None&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; cache&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;insert&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;target&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; num&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; idx&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;),&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            };&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;        unreachable!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/add-two-numbers/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given two &lt;strong&gt;non-empty&lt;/strong&gt; linked lists representing two non-negative integers. The digits are stored in &lt;strong&gt;reverse order&lt;/strong&gt;, and each of their nodes contains a single digit. Add the two numbers and return the sum as a linked list.&lt;/p&gt;
&lt;p&gt;You may assume the two numbers do not contain any leading zero, except the number 0 itself.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;/images/add-two-numbers/addtwonumber1.jpg&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; l1 = [2,4,3], l2 = [5,6,4]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [7,0,8]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; 342 + 465 = 807.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; l1 = [0], l2 = [0]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [0]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; l1 = [9,9,9,9,9,9,9], l2 = [9,9,9,9]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [8,9,9,9,0,0,0,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;The number of nodes in each linked list is in the range &lt;code&gt;[1, 100]&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;&lt;code&gt;0 &amp;lt;= Node.val &amp;lt;= 9&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;It is guaranteed that the list represents a number that does not have leading zeros.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// Definition for singly-linked list.&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// #[derive(PartialEq, Eq, Clone, Debug)]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// pub struct ListNode {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//   pub val: i32,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//   pub next: Option&amp;lt;Box&amp;lt;ListNode&amp;gt;&amp;gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// &lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// impl ListNode {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//   #[inline]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//   fn new(val: i32) -&amp;gt; Self {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//     ListNode {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//       next: None,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//       val&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//     }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;//   }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; add_two_numbers&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Box&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;ListNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Box&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;ListNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    )&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Box&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;ListNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; carry&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // this is the core trick of this solution&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // curr actually point to the tail of added result&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // so we could keep appending new digit to it&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // without dummy node and unwrap operations&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; head&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Box&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;ListNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; None&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; curr&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; = &amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; head&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        while&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;is_some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; ||&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;is_some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; ||&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; carry&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; !=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // unify our logic for any situation&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            carry&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +=&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;as_ref&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;val&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;                +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;as_ref&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;val&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // append new digit&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;            let&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; sum_node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; curr&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;insert&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Box&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;new&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;ListNode&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;new&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;carry&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // update curr&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            curr&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; = &amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; sum_node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;next&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            carry&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; /=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // update l1 &amp;amp; l2&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            l1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;and_then&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;next&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            l2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; l2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;and_then&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;next&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        head&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/palindrome-number/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Given an integer &lt;code&gt;x&lt;/code&gt;, return &lt;code&gt;true&lt;/code&gt; if &lt;code&gt;x&lt;/code&gt; is a &lt;strong&gt;palindrome&lt;/strong&gt;, and &lt;code&gt;false&lt;/code&gt; otherwise.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; x = 121&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; true&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; 121 reads as 121 from left to right and from right to left.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; x = -121&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; false&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; From left to right, it reads -121. From right to left, it becomes 121-. Therefore it is not a palindrome.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; x = 10&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; false&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; Reads 01 from right to left. Therefore it is not a palindrome.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;-2^31 &amp;lt;= x &amp;lt;= 2^31 - 1&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Follow up:&lt;/strong&gt; Could you solve it without converting the integer to a string?&lt;/p&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; is_palindrome&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; bool&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; reverse&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; tmp&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // if x is negative, it is not palindrome&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        if&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;            return&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; false&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // construct a reversed number&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        while&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; tmp&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            reverse&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; reverse&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; *&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; tmp&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            tmp&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; /=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // by definition&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        reverse&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/container-with-most-water/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given an integer array &lt;code&gt;height&lt;/code&gt; of length &lt;code&gt;n&lt;/code&gt;. There are &lt;code&gt;n&lt;/code&gt; vertical lines drawn such that the two endpoints of the &lt;code&gt;i^th&lt;/code&gt; line are &lt;code&gt;(i, 0)&lt;/code&gt; and &lt;code&gt;(i, height[i])&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;Find two lines that together with the x-axis form a container, such that the container contains the most water.&lt;/p&gt;
&lt;p&gt;Return &lt;em&gt;the maximum amount of water a container can store&lt;/em&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Notice&lt;/strong&gt; that you may not slant the container.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;/images/container-with-most-water/question_11.jpg&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; height = [1,8,6,2,5,4,8,3,7]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 49&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The above vertical lines are represented by array [1,8,6,2,5,4,8,3,7]. In this case, the max area of water (blue section) the container can contain is 49.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; height = [1,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;n == height.length&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;2 &amp;lt;= n &amp;lt;= 10^5&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;0 &amp;lt;= height[i] &amp;lt;= 10^4&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;    // area = W x H, if we start at the leftmost and rightmost lines,&lt;/span&gt;&lt;/span&gt;
