&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;                .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;iter_mut&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // get one char from each iterator&lt;/span&gt;&lt;/span&gt;
