&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;                };&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;                min&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;next &lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;=&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; Self&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;merge_two_lists&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;min&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;next&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;max&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;                Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;min&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
