&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;use&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;rc&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Rc&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;use&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;cell&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;RefCell&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; is_same_tree&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        p&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Rc&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;RefCell&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;TreeNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;&amp;gt;,&lt;/span&gt;&lt;span&gt; &lt;/span&gt;&lt;/span&gt;
