&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;    // we solve this by iterate through symmertric pair of nodes a pair of&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;    // symmertric node should have the same value and mirrored children nodes&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; is_symmetric&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;root&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Option&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Rc&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;RefCell&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;TreeNode&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; bool&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; nodes&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[];&lt;/span&gt;&lt;/span&gt;
