&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/1-bit-and-2-bit-characters/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;We have two special characters:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;The first character can be represented by one bit &lt;code&gt;0&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;The second character can be represented by two bits (&lt;code&gt;10&lt;/code&gt; or &lt;code&gt;11&lt;/code&gt;).&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Given a binary array &lt;code&gt;bits&lt;/code&gt; that ends with &lt;code&gt;0&lt;/code&gt;, return &lt;code&gt;true&lt;/code&gt; if the last character must be a one-bit character.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; bits = [1,0,0]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; true&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The only way to decode it is two-bit character and one-bit character.&lt;/p&gt;
&lt;p&gt;So the last character is one-bit character.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; bits = [1,1,1,0]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; false&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The only way to decode it is two-bit character and two-bit character.&lt;/p&gt;
&lt;p&gt;So the last character is not one-bit character.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= bits.length &amp;lt;= 1000&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;bits[i]&lt;/code&gt; is either &lt;code&gt;0&lt;/code&gt; or &lt;code&gt;1&lt;/code&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; is_one_bit_character&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;bits&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; bool&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // solution count 1s from the right end&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        bits&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;into_iter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;rev&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;skip&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;take_while&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;b&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; b&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;count&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/delete-and-earn/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given an integer array &lt;code&gt;nums&lt;/code&gt;. You want to maximize the number of points you get by performing the following operation any number of times:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Pick any &lt;code&gt;nums[i]&lt;/code&gt; and delete it to earn &lt;code&gt;nums[i]&lt;/code&gt; points. Afterwards, you must delete &lt;strong&gt;every&lt;/strong&gt; element equal to &lt;code&gt;nums[i] - 1&lt;/code&gt; and &lt;strong&gt;every&lt;/strong&gt; element equal to &lt;code&gt;nums[i] + 1&lt;/code&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Return &lt;em&gt;the &lt;strong&gt;maximum number of points&lt;/strong&gt; you can earn by applying the above operation some number of times&lt;/em&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [3,4,2]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 6&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; You can perform the following operations:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Delete 4 to earn 4 points. Consequently, 3 is also deleted. nums = [2].&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Delete 2 to earn 2 points. nums = [].&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You earn a total of 6 points.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [2,2,3,3,3,4]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 9&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; You can perform the following operations:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Delete a 3 to earn 3 points. All 2’s and 4’s are also deleted. nums = [3,3].&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Delete a 3 again to earn 3 points. nums = [3].&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Delete a 3 once more to earn 3 points. nums = [].&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You earn a total of 9 points.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= nums.length &amp;lt;= 2 * 10^4&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= nums[i] &amp;lt;= 10^4&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// we solve this by state machine thinking&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// first we collect numbers by their value&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// then we iterate through each of them&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// in each step, we have several state and corresponding&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// options&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// take: we have taken the previous number, we can only skip&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// the current one, after the current one, we transition to&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// skip state.&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// skip: we have not taken the previous number, in turn we can&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// take the current number, and we must choose take the current&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// number or not, so we compare take &amp;amp; (skip + current), and&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// choose the maxmium&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; delete_and_earn&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // by question constraints, we have 10000&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; cnt&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10001&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;];&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        for&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; in&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; nums&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            cnt&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; usize&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;]&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +=&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        cnt&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;into_iter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;fold&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;),&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;skip&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; take&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;),&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; val&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // take -&amp;gt; skip&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // max(take, skip + val) -&amp;gt; take&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;                (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;take&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; take&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;max&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;skip&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; val&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            })&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // from our transition we can see take is always&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // bigger than skip&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/partition-labels/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given a string &lt;code&gt;s&lt;/code&gt;. We want to partition the string into as many parts as possible so that each letter appears in at most one part. For example, the string &lt;code&gt;&quot;ababcc&quot;&lt;/code&gt; can be partitioned into &lt;code&gt;[&quot;abab&quot;, &quot;cc&quot;]&lt;/code&gt;, but partitions such as &lt;code&gt;[&quot;aba&quot;, &quot;bcc&quot;]&lt;/code&gt; or &lt;code&gt;[&quot;ab&quot;, &quot;ab&quot;, &quot;cc&quot;]&lt;/code&gt; are invalid.&lt;/p&gt;
&lt;p&gt;Note that the partition is done so that after concatenating all the parts in order, the resultant string should be &lt;code&gt;s&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;Return &lt;em&gt;a list of integers representing the size of these parts&lt;/em&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; s = “ababcbacadefegdehijhklij”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [9,7,8]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;The partition is “ababcbaca”, “defegde”, “hijhklij”.&lt;/p&gt;
&lt;p&gt;This is a partition so that each letter appears in at most one part.&lt;/p&gt;
&lt;p&gt;A partition like “ababcbacadefegde”, “hijhklij” is incorrect, because it splits s into less parts.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; s = “eccbbbbdec”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [10]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= s.length &amp;lt;= 500&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;s&lt;/code&gt; consists of lowercase English letters.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// we solve this by marking last occurrence of each char&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// we just merge intervals on the way&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; partition_labels&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;s&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; String&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // this should be right I think?&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; last&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;collections&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;HashMap&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;char&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; usize&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            s&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;chars&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;enumerate&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; ch&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;ch&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; idx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;collect&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;();&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; start&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt; mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; end&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; parts&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[];&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        for&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; ch&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; in&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; s&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;chars&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;enumerate&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;() {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // update the end index&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            end&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; end&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;max&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;*&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;last&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;get&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;ch&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;unwrap_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // we&amp;#39;ve reached the end&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;            if&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; idx&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; end&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;                parts&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;push&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;end&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; start&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;                start&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; idx&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        parts&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/stone-game/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Alice and Bob play a game with piles of stones. There are an &lt;strong&gt;even&lt;/strong&gt; number of piles arranged in a row, and each pile has a &lt;strong&gt;positive&lt;/strong&gt; integer number of stones &lt;code&gt;piles[i]&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;The objective of the game is to end with the most stones. The &lt;strong&gt;total&lt;/strong&gt; number of stones across all the piles is &lt;strong&gt;odd&lt;/strong&gt;, so there are no ties.&lt;/p&gt;
&lt;p&gt;Alice and Bob take turns, with &lt;strong&gt;Alice starting first&lt;/strong&gt;. Each turn, a player takes the entire pile of stones either from the &lt;strong&gt;beginning&lt;/strong&gt; or from the &lt;strong&gt;end&lt;/strong&gt; of the row. This continues until there are no more piles left, at which point the person with the &lt;strong&gt;most stones wins&lt;/strong&gt;.&lt;/p&gt;
&lt;p&gt;Assuming Alice and Bob play optimally, return &lt;code&gt;true&lt;/code&gt; &lt;em&gt;if Alice wins the game, or&lt;/em&gt; &lt;code&gt;false&lt;/code&gt; &lt;em&gt;if Bob wins&lt;/em&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; piles = [5,3,4,5]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; true&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Alice starts first, and can only take the first 5 or the last 5.&lt;/p&gt;
&lt;p&gt;Say she takes the first 5, so that the row becomes [3, 4, 5].&lt;/p&gt;
&lt;p&gt;If Bob takes 3, then the board is [4, 5], and Alice takes 5 to win with 10 points.&lt;/p&gt;
&lt;p&gt;If Bob takes the last 5, then the board is [3, 4], and Alice takes 4 to win with 9 points.&lt;/p&gt;
&lt;p&gt;This demonstrated that taking the first 5 was a winning move for Alice, so we return true.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; piles = [3,7,2,3]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; true&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;2 &amp;lt;= piles.length &amp;lt;= 500&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;piles.length&lt;/code&gt; is &lt;strong&gt;even&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= piles[i] &amp;lt;= 500&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;sum(piles[i])&lt;/code&gt; is &lt;strong&gt;odd&lt;/strong&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; stone_game&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;piles&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; bool&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // it is actually not obvious that alice will always win&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // let think it this way&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // Alice always wins because she can force the game to take all piles&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // from either the even or odd positions, and since the total is odd,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // one group has more stones.&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // So she just picks the larger group and mirrors Bob&amp;#39;s moves&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;        true&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/sum-of-subarray-minimums/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Given an array of integers arr, find the sum of &lt;code&gt;min(b)&lt;/code&gt;, where &lt;code&gt;b&lt;/code&gt; ranges over every (contiguous) subarray of &lt;code&gt;arr&lt;/code&gt;. Since the answer may be large, return the answer &lt;strong&gt;modulo&lt;/strong&gt; &lt;code&gt;10^9 + 7&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; arr = [3,1,2,4]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 17&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Subarrays are [3], [1], [2], [4], [3,1], [1,2], [2,4], [3,1,2], [1,2,4], [3,1,2,4].&lt;/p&gt;
&lt;p&gt;Minimums are 3, 1, 2, 4, 1, 1, 2, 1, 1, 1.&lt;/p&gt;
&lt;p&gt;Sum is 17.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; arr = [11,81,94,43,3]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 444&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= arr.length &amp;lt;= 3 * 10^4&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= arr[i] &amp;lt;= 3 * 10^4&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; sum_subarray_mins&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;arr&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
