&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        root&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;as_ref&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;is_none_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;node&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;            let&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;borrow&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;();&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;            dfs&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;left&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;val&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; &amp;amp;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; dfs&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;right&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; node&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span&gt;val&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        })&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/largest-perimeter-triangle/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Given an integer array &lt;code&gt;nums&lt;/code&gt;, return &lt;em&gt;the largest perimeter of a triangle with a non-zero area, formed from three of these lengths&lt;/em&gt;. If it is impossible to form any triangle of a non-zero area, return &lt;code&gt;0&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [2,1,2]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 5&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; You can form a triangle with three side lengths: 1, 2, and 2.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [1,2,1,10]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 0&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;You cannot use the side lengths 1, 1, and 2 to form a triangle.&lt;/p&gt;
&lt;p&gt;You cannot use the side lengths 1, 1, and 10 to form a triangle.&lt;/p&gt;
&lt;p&gt;You cannot use the side lengths 1, 2, and 10 to form a triangle.&lt;/p&gt;
&lt;p&gt;As we cannot use any three side lengths to form a triangle of non-zero area, we return 0.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;3 &amp;lt;= nums.length &amp;lt;= 10^4&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= nums[i] &amp;lt;= 10^6&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// assume the length of the 3 edges are: a, b, c and&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// a &amp;gt;= b &amp;gt;= c, to construct a valid triangle, we must&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// have: a &amp;lt; b + c&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// sort the array in descending order, to search for&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// the largest perimeter triangle, we can just search&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// with a sliding window of size 3, and choose the first&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// window that can construct a valid triangle.&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// we could also solve this with binary heap, which have&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// O(N) time complexity in best case. (O(NlogN) worst case)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// apparently construct a binary heap from a vec can be done&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// in-place and in O(N) time&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; largest_perimeter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;sort_unstable_by&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; r&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; r&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;cmp&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;l&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;windows&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;3&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;find&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;w&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; w&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;]&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; w&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;]&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; w&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;2&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;])&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;w&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; w&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;iter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;sum&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;())&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/smallest-integer-divisible-by-k/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Given a positive integer &lt;code&gt;k&lt;/code&gt;, you need to find the &lt;strong&gt;length&lt;/strong&gt; of the &lt;strong&gt;smallest&lt;/strong&gt; positive integer &lt;code&gt;n&lt;/code&gt; such that &lt;code&gt;n&lt;/code&gt; is divisible by &lt;code&gt;k&lt;/code&gt;, and &lt;code&gt;n&lt;/code&gt; only contains the digit &lt;code&gt;1&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;Return &lt;em&gt;the &lt;strong&gt;length&lt;/strong&gt; of&lt;/em&gt; &lt;code&gt;n&lt;/code&gt;. If there is no such &lt;code&gt;n&lt;/code&gt;, return -1.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Note:&lt;/strong&gt; &lt;code&gt;n&lt;/code&gt; may not fit in a 64-bit signed integer.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; k = 1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The smallest answer is n = 1, which has length 1.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; k = 2&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; -1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; There is no such positive integer n divisible by 2.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; k = 3&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 3&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The smallest answer is n = 111, which has length 3.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= k &amp;lt;= 10^5&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; smallest_repunit_div_by_k&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;k&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // infinite iterator&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;        std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;iter&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;successors&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;),&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; *&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 10&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; k&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // we have at most k items, otherwise it&amp;#39;s a cycle&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;zip&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;..=&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;k&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // the m % k exist to special case k == 1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;find&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; _&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; m&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; k&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map_or&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;-&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;_&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; i&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; i&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/binary-prefix-divisible-by-5/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;You are given a binary array &lt;code&gt;nums&lt;/code&gt; (&lt;strong&gt;0-indexed&lt;/strong&gt;).&lt;/p&gt;
&lt;p&gt;We define &lt;code&gt;x_i&lt;/code&gt; as the number whose binary representation is the subarray &lt;code&gt;nums[0..i]&lt;/code&gt; (from most-significant-bit to least-significant-bit).&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;For example, if &lt;code&gt;nums = [1,0,1]&lt;/code&gt;, then &lt;code&gt;x_0 = 1&lt;/code&gt;, &lt;code&gt;x_1 = 2&lt;/code&gt;, and &lt;code&gt;x_2 = 5&lt;/code&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Return &lt;em&gt;an array of booleans&lt;/em&gt; &lt;code&gt;answer&lt;/code&gt; &lt;em&gt;where&lt;/em&gt; &lt;code&gt;answer[i]&lt;/code&gt; &lt;em&gt;is&lt;/em&gt; &lt;code&gt;true&lt;/code&gt; &lt;em&gt;if&lt;/em&gt; &lt;code&gt;x_i&lt;/code&gt; &lt;em&gt;is divisible by&lt;/em&gt; &lt;code&gt;5&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [0,1,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [true,false,false]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; The input numbers in binary are 0, 01, 011; which are 0, 1, and 3 in base-10.&lt;/p&gt;
&lt;p&gt;Only the first number is divisible by 5, so answer[0] is true.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; nums = [1,1,1]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; [false,false,false]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= nums.length &amp;lt;= 10^5&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;nums[i]&lt;/code&gt; is either &lt;code&gt;0&lt;/code&gt; or &lt;code&gt;1&lt;/code&gt;.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; prefixes_div_by5&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;bool&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        nums&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;into_iter&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;scan&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; v&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;                *&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;*&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; *&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 2&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; v&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; %&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 5&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;                Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;*&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;m&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            })&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;collect&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/shortest-path-in-binary-matrix/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;Given an &lt;code&gt;n x n&lt;/code&gt; binary matrix &lt;code&gt;grid&lt;/code&gt;, return &lt;em&gt;the length of the shortest &lt;strong&gt;clear path&lt;/strong&gt; in the matrix&lt;/em&gt;. If there is no clear path, return &lt;code&gt;-1&lt;/code&gt;.&lt;/p&gt;
&lt;p&gt;A &lt;strong&gt;clear path&lt;/strong&gt; in a binary matrix is a path from the &lt;strong&gt;top-left&lt;/strong&gt; cell (i.e., &lt;code&gt;(0, 0)&lt;/code&gt;) to the &lt;strong&gt;bottom-right&lt;/strong&gt; cell (i.e., &lt;code&gt;(n - 1, n - 1)&lt;/code&gt;) such that:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;All the visited cells of the path are &lt;code&gt;0&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;All the adjacent cells of the path are &lt;strong&gt;8-directionally&lt;/strong&gt; connected (i.e., they are different and they share an edge or a corner).&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The &lt;strong&gt;length of a clear path&lt;/strong&gt; is the number of visited cells of this path.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;/images/shortest-path-in-binary-matrix/example1_1.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; grid = [[0,1],[1,0]]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 2&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;img src=&quot;/images/shortest-path-in-binary-matrix/example2_1.png&quot; alt=&quot;&quot; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; grid = [[0,0,0],[1,1,0],[1,1,0]]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 4&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; grid = [[1,0,0],[1,1,0],[1,1,0]]&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; -1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;n == grid.length&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;n == grid[i].length&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;1 &amp;lt;= n &amp;lt;= 100&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;grid[i][j] is 0 or 1&lt;/code&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// BFS with double queue&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; shortest_path_binary_matrix&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; grid&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;Vec&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;&amp;gt;&amp;gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // 8 directions&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        #[&lt;/span&gt;&lt;span&gt;rustfmt&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span&gt;skip&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; dirs&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; [&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            [&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            [&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;-&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;-&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;], [&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;-&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;],&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        ];&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; grid&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;len&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // double &amp;quot;queue&amp;quot;, order doesn&amp;#39;t matter here&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; queue&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt; mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; swp&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[],&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; vec!&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[]);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; steps&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;        queue&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;push&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;0&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // helper lambda to check range &amp;amp; visited&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // this has the side effect of marking grid[x][y] as visited&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;        let mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; out_of_range_or_visited&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; |&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;            !&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;gt;=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; &amp;amp;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; &amp;amp;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;gt;=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; &amp;amp;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                ||&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;mem&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;replace&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; grid&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;[&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; usize&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;][&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;y&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; usize&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;],&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;                    !=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 0&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        };&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;        while !&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;queue&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;is_empty&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;() {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // keep track of steps&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;            steps&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +=&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;            while&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt; let&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Some&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; =&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; queue&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;pop&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;() {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // check range and value and mark visited&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                if&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; out_of_range_or_visited&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;) {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                    continue&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;                }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // reach destination, return&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                if&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; &amp;amp;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; ==&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; n&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt; 1&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                    return&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; steps&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;                }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;                // push adjacent cells to another queue&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;                for&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; [&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;dx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; dy&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;]&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; in&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; dirs&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;                    swp&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;.&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;push&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;((&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; dx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; dy&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;));&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;                }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;            }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;            // alternate between two queues&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;            std&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;mem&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;::&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;swap&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;&amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; queue&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;amp;&lt;/span&gt;&lt;span style=&quot;color: #FE8019;&quot;&gt;mut&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; swp&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;);&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;        }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;        // unreachable&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;        -&lt;/span&gt;&lt;span style=&quot;color: #D3869B;&quot;&gt;1&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;    }&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;

&lt;h3 id=&quot;description-leetcode&quot;&gt;Description (&lt;a rel=&quot;noopener external&quot; target=&quot;_blank&quot; href=&quot;https://leetcode.com/problems/split-a-string-in-balanced-strings/&quot;&gt;leetcode&lt;/a&gt;)&lt;/h3&gt;
&lt;p&gt;&lt;strong&gt;Balanced&lt;/strong&gt; strings are those that have an equal quantity of &lt;code&gt;&apos;L&apos;&lt;/code&gt; and &lt;code&gt;&apos;R&apos;&lt;/code&gt; characters.&lt;/p&gt;
&lt;p&gt;Given a &lt;strong&gt;balanced&lt;/strong&gt; string &lt;code&gt;s&lt;/code&gt;, split it into some number of substrings such that:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Each substring is balanced.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Return &lt;em&gt;the &lt;strong&gt;maximum&lt;/strong&gt; number of balanced strings you can obtain.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 1:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; s = “RLRRLLRLRL”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 4&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; s can be split into “RL”, “RRLL”, “RL”, “RL”, each substring contains same number of ‘L’ and ‘R’.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 2:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; s = “RLRRRLLRLL”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 2&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; s can be split into “RL”, “RRRLLRLL”, each substring contains same number of ‘L’ and ‘R’.&lt;/p&gt;
&lt;p&gt;Note that s cannot be split into “RL”, “RR”, “RL”, “LR”, “LL”, because the 2^nd and 5^th substrings are not balanced.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Example 3:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Input:&lt;/strong&gt; s = “LLLLRRRR”&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Output:&lt;/strong&gt; 1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Explanation:&lt;/strong&gt; s can be split into “LLLLRRRR”.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Constraints:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;2 &amp;lt;= s.length &amp;lt;= 1000&lt;/code&gt;&lt;/li&gt;
&lt;li&gt;&lt;code&gt;s[i]&lt;/code&gt; is either &lt;code&gt;&apos;L&apos;&lt;/code&gt; or &lt;code&gt;&apos;R&apos;&lt;/code&gt;.&lt;/li&gt;
&lt;li&gt;&lt;code&gt;s&lt;/code&gt; is a &lt;strong&gt;balanced&lt;/strong&gt; string.&lt;/li&gt;
&lt;/ul&gt;
&lt;hr /&gt;
&lt;h3 id=&quot;submission&quot;&gt;submission&lt;/h3&gt;
&lt;pre class=&quot;giallo&quot; style=&quot;color: #EBDBB2; background-color: #282828;&quot; &gt;&lt;code data-lang=&quot;rust&quot;&gt;&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #928374;font-style: italic;&quot;&gt;// one line with scan and filter and count&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;impl&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; Solution&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;    pub fn&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; balanced_string_split&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;s&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;:&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; String&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; -&amp;gt;&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;/span&gt;
