&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;rev&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;enumerate&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;()&lt;/span&gt;&lt;/span&gt;
&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;            .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;, (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;x&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;| if&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;idx&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; as&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt; i32&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; &amp;lt;&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; k&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; x&lt;/span&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt; +&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; }&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt; else&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; {&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; y&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; })&lt;/span&gt;&lt;/span&gt;
