&lt;span class=&quot;giallo-l&quot;&gt;&lt;span style=&quot;color: #8EC07C;&quot;&gt;                    .&lt;/span&gt;&lt;span style=&quot;color: #FABD2F;&quot;&gt;map&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;(&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;v&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; c&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;)&lt;/span&gt;&lt;span style=&quot;color: #FB4934;&quot;&gt;|&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt; (&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt;c&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;,&lt;/span&gt;&lt;span style=&quot;color: #83A598;&quot;&gt; v&lt;/span&gt;&lt;span style=&quot;color: #A89984;&quot;&gt;))&lt;/span&gt;&lt;/span&gt;
